input.command:
p=$(git ls-tree -r --name-only entire/1aabf36-e3b0c4 | grep 2b9ee4a2) && echo "$p" && f=$(echo "$p" | grep prompt.txt) && git show entire/1aabf36-e3b0c4:"$f" | cut -c1-1500 && echo '=== transcript tail' && j=$(echo "$p" | grep full.jsonl) && git show entire/1aabf36-e3b0c4:"$j" | tail -40 | python3 -I -c '
import json,sys
for l in sys.stdin:
    try: d=json.loads(l)
    except Exception: continue
    m=d.get("message",{})
    c=m.get("content")
    role=m.get("role") or d.get("type")
    if isinstance(c,str): print(role,":",c[:1200]); continue
    for b in c or []:
        t=b.get("type")
        if t=="text": print(role,": TEXT",b["text"][:1500])
        elif t=="tool_use": print(role,": TOOL",json.dumps(b.get("input"))[:500])
        elif t=="tool_result":
            r=b.get("content"); r=r if isinstance(r,str) else json.dumps(r)
            print(role,": RESULT",r[:700])
'

